# -*- coding: utf-8 -*-
import re, psycopg2
S = "контрольная выборка №6 и сквозные проверки вариантов, равных ключу / служебных пометок в тексте (30.09), проверено вычислением"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
EQ = "неверный вариант равен ключу; заменён на реальную ошибку"

E("G5_TB_16_660.1", "неверный вариант $-5$ — тоже корень уравнения $x\\cdot x=25$; заменён на реальную ошибку",
  dnew={1: (r"$625$", r"Ученик возвёл $25$ в квадрат вместо извлечения корня.")})
E("G11_TB_§4_4_58_2", EQ + " ($-\\sin(x^4)\\cdot4x^3$ равно ключу)",
  dnew={2: (r"$-\sin(x^{4})$", r"Ученик забыл множитель $4x^{3}$ — производную внутренней функции.")})
E("G9_TB_6_82_3", "неверный вариант «рациональным, $28$» верен (совпадает с ключом и уточняет значение); заменён на реальную ошибку",
  dnew={2: ("нельзя определить", r"Ученик решил, что при наличии $\sqrt5$ определить тип числа без вычислений нельзя.")})
E("G6_TB_18_722.7", "в условии смешанное число $6\\frac56$ было разорвано на «$6:\\frac56$» (ключ $\\frac56$ верен для $6\\frac56:8{,}2=\\frac{41}{6}:\\frac{41}{5}$)",
  q=r"Найдите отношение $6\dfrac{5}{6}$ к $8{,}2$")
E("G9_TB_16_182_1", "$-x^2-6x-8\\ge0 \\Leftrightarrow x\\in[-4;-2]$, $\\frac13x+2\\ge0 \\Leftrightarrow x\\ge-6$; область определения $[-4;-2]$ (в ключе стояло $[-6;-4]\\cup[-2;+\\infty)$)",
  k=r"$x \in [-4; -2]$",
  dnew={0: (r"$x \in [-6; -4]$", r"Ученик неверно нашёл промежуток, где $-x^{2}-6x-8\ge0$, и взял его левую часть."),
        1: (r"$x \in [-6; -2]$", r"Ученик взял левую границу из условия $x\ge-6$, не пересекая с промежутком $[-4;-2]$."),
        2: (r"$x \in [-4; -2] \cup [-2; +\infty)$", r"Ученик решил первое неравенство верно, но вместо пересечения с условием $x\ge-6$ объединил промежутки.")})
E("G10_TB_§5_5_10_3", "неверный вариант $(-\\infty;1]\\cup[2;+\\infty)$ равен ключу как множество (точка $-0{,}5$ уже лежит в $(-\\infty;1]$); заменён на реальную ошибку",
  dnew={1: (r"$x \in (-\infty; -0{,}5) \cup (-0{,}5; 1] \cup [2; +\infty)$", r"Ученик исключил точку $x=-0{,}5$, хотя при ней левая часть равна нулю и неравенство нестрогое.")})
E("G8_TB_1_9.1", EQ, dnew={2: (r"$\dfrac{x}{x+y}$", r"Ученик потерял множитель $y$ в числителе.")})
E("G8_TB_11_285.3", EQ + " ($-\\frac{a}{a^3-1}=\\frac{a}{1-a^3}$)",
  dnew={0: (r"$\dfrac{a}{a^{3} - 1}$", r"Ученик потерял знак минус при приведении к общему знаменателю $1-a^{3}$.")})
E("G8_ALG_10_148.4", EQ + " ($-\\frac{27b-5}{36}=\\frac{5-27b}{36}$)",
  dnew={0: (r"$\dfrac{5-9b}{36}$", r"Ученик ошибся в коэффициенте при $b$ после приведения к знаменателю $36$.")})
E("G10_TB_3_1_5_1", EQ + " ($c^{-\\sqrt9}=c^{-3}$)",
  dnew={1: (r"$1$", r"Ученик сложил показатели $-\sqrt{3}+\sqrt{3}=0$ вместо умножения.")})
E("G11_TB_22_4_3", EQ + " ($\\frac2T-\\frac1{T^2}=\\frac{2T-1}{T^2}$)",
  dnew={1: (r"$\dfrac{2T+1}{T^{2}}$", r"Ученик ошибся в знаке при вычитании площади угловых треугольников.")})
E("G10_TB_§36_36_19_3", EQ + " (то же выражение другой записью)",
  dnew={1: (r"$\cos x \cos 2x + 2\sin x \sin 2x$", r"Ученик перепутал знак между слагаемыми производной произведения.")})
E("G7_TB_20_466.5", EQ + " ($(a^m)^n=a^{nm}$)",
  dnew={2: (r"$(am)^{n}$", r"Ученик ошибочно перемножил основание $a$ и внешний показатель $m$.")})
E("G10_TB_§35_35_2_4", EQ + " (та же запись $\\frac15x^{-4/5}$)",
  dnew={2: (r"$\dfrac{1}{5}x^{-\dfrac{6}{5}}$", r"Ученик прибавил $1$ к показателю вместо вычитания: $\dfrac{1}{5}+1$ в знаменателе.")})
E("G10_TB_§35_35_4_1", EQ + " (та же запись $\\frac14x^{-3/4}$)",
  dnew={2: (r"$\dfrac{1}{4}x^{-\dfrac{5}{4}}$", r"Ученик прибавил $1$ к показателю вместо вычитания.")})
E("G10_TB_§35_35_5_3", EQ + " (тот же ответ $-\\frac7{12}x^{-19/12}$)",
  dnew={1: (r"$\dfrac{7}{12}x^{-\dfrac{19}{12}}$", r"Ученик потерял знак минус при дифференцировании степени с отрицательным показателем.")})
E("G10_TB_§35_35_5_2", EQ + " (тот же ответ $\\frac56x^{-1/6}$)",
  dnew={0: (r"$\dfrac{5}{6}x^{\dfrac{1}{6}}$", r"Ученик потерял знак минус у показателя: $\dfrac{5}{6}-1=\dfrac{1}{6}$.")})
E("G10_TB_§35_35_4_3", EQ + " (тот же ответ $-\\frac12x^{-3/2}$)",
  dnew={2: (r"$\dfrac{1}{2}x^{-\dfrac{3}{2}}$", r"Ученик потерял знак минус при дифференцировании степени с отрицательным показателем.")})
E("G6_TB_42_1491.4", "неверный вариант «$-\\frac9{10}<-\\frac78$ (но с неверным обоснованием)» — верное неравенство, к тому же с служебной пометкой; заменён",
  dnew={2: (r"$\dfrac{-7}{8} < \dfrac{-9}{10}$", r"Ученик записал дроби в обратном порядке, не сверив знак неравенства.")})
E("G9_TB_3_25_д", "неверный вариант «$-2{,}882<-2\\frac{13}{20}$ (но с обоснованием …)» — то же верное неравенство, что и ключ, с служебной пометкой; заменён",
  dnew={1: (r"$-2{,}882 = -2 \dfrac{13}{20}$", r"Ученик решил, что $2{,}882$ и $2\dfrac{13}{20}$ отличаются лишь записью, и назвал числа равными.")})
E("G6_TB_118–119_1018", "в ключе $58\\cdot96=12\\cdot464$ цифры $4$ и $6$ повторяются, а $3$ и $7$ не использованы; перебором единственное решение $58\\cdot96=32\\cdot174=5568$ (все цифры $1$–$9$ по одному разу)",
  k=r"$58 \cdot 96 = 32 \cdot 174 = 5568$",
  dnew={0: (r"$58 \cdot 96 = 12 \cdot 464 = 5568$", r"Равенство верно, но цифры $4$ и $6$ повторяются, а $3$ и $7$ не использованы.")})
E("G5_TB_20_809.1", "неверный вариант с пометкой «но расчёт велся как …» совпадал с ключом по значению; заменён на реальную ошибку",
  dnew={2: (r"$300$ м/мин и $250$ м/мин", r"Скорости в сумме дают $550$ м/мин, а не $450$ м/мин ($2700:6$): ученик ошибся при нахождении скорости сближения.")})
E("G11_TB_§4_10_2", "неверный вариант с пометкой «но с условием …» совпадал с ключом; заменён на реальную ошибку",
  dnew={2: (r"$x = \pm \dfrac{2\pi}{3} + 2\pi k$, $k \in \mathbb{Z}$", r"Ученик решил уравнение $\cos x=-\dfrac{1}{2}$ вместо $\cos x=\dfrac{1}{2}$.")})
E("G11_TB_15_4*_15_24_b", "неверный вариант $x=a-\\frac{a+2}{a+1}$ равен ключу (то же выражение для $x$); английское «no solutions» заменено",
  dnew={2: (r"$a = -1$: нет решений; $a \neq -1$: $x = \dfrac{a^{2} + 2}{a + 1}$, $y = \dfrac{a+2}{a+1}$", r"Ученик ошибся в знаке при подстановке $y$ во второе уравнение: $x=a+y$.")})
E("G11_TB_15_4*_15_24_c", "английские слова в неверных вариантах заменены русскими",
  dnew={1: (r"$a = 1$: $x$ — любое, $y = 4$; $a \neq 1$: $x = a + \dfrac{a + 3}{a - 1}$, $y = \dfrac{a + 3}{a - 1}$", r"Уравнение $0\cdot y=4$ не имеет решений ни при каком $y$. Ученик ошибочно посчитал, что $y=4$ является корнем."),
        2: (r"$a = 1$: нет решений; $a \neq 1$: $x = \dfrac{a+3}{a-1}$, $y = \dfrac{a+3}{a-1}$", r"Ученик приравнял $x$ к $y$, не прибавив параметр $a$ из второго уравнения.")})
E("G11_TB_15_4*_15_24_d", "неверный вариант с «no solutions» равен ключу по содержанию; заменён; английское «any» заменено",
  dnew={0: (r"$a = -1$: нет решений; $a \neq -1$: $x = \dfrac{a^{2} + 4}{a + 1}$, $y = \dfrac{a + 4}{a + 1}$", r"Ученик потерял слагаемое $2a$ в числителе для $x$."),
        1: (r"$a = -1$: $x$ и $y$ — любые; $a \neq -1$: $x = \dfrac{a^{2} + 2a + 4}{a + 1}$, $y = \dfrac{a + 4}{a + 1}$", r"При $a=-1$ получается $0=3$; ученик принял это за тождество и решил, что решений бесконечно много.")})

# служебные пометки в тексте условий: «(в тексте опечатка …)»
conn = psycopg2.connect("postgresql://algo:algo_password@algo-content-db:5432/algo_content"); cur = conn.cursor()
cur.execute("select id, question_latex from tasks_master where is_active and question_latex ~ 'в тексте опечатка'")
for tid, q in cur.fetchall():
    nq = re.sub(r"\s*\(в тексте опечатка[^)]*\)", "", q)
    assert nq != q
    E(tid, "служебная пометка «(в тексте опечатка …)» удалена из условия (остатки работы генератора)", q=nq)
